-- Every recorded earthquake magnitude 2.5+ worldwide -- 443K events with time, place, and depth.
-- Auto-generated by scripts/gen_evidence_pages.py: 443,274 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("UPDATED") as year, count(*) as records
from THE_LIBRARY.SCIENCE.EARTHQUAKES
where "UPDATED" is not null
group by 1
order by 1
